diff --git i/internal/ui/security/model.go w/internal/ui/security/model.go
index 031e0587..967ec776 100644
--- i/internal/ui/security/model.go
+++ w/internal/ui/security/model.go
@@ -224,6 +224,9 @@ func (m *Model) setResult(result *scan.Result) {
 	m.targetPath = result.Target
 	m.targetLabel = labelForResult(m.config, result)
